package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// validateTableName checks against known tables
func validateTableName(table string) bool {
	allowed := []string{"products", "categories", "reviews", "inventory"}
	for _, t := range allowed {
		if strings.EqualFold(table, t) {
			return true
		}
	}
	return false
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	table := r.URL.Query().Get("table")
	column := r.URL.Query().Get("col")
	term := r.URL.Query().Get("q")

	if table == "" || column == "" || term == "" {
		http.Error(w, "Missing parameters", http.StatusBadRequest)
		return
	}

	table = sanitizeInput(table)
	column = sanitizeInput(column)
	term = sanitizeInput(term)

	if !validateTableName(table) {
		http.Error(w, "Invalid table", http.StatusBadRequest)
		return
	}

	// Column validation - only allow alphanumeric and underscore
	for _, c := range column {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			http.Error(w, "Invalid column name", http.StatusBadRequest)
			return
		}
	}

	// Build query - term is user-controlled and concatenated directly
	query := fmt.Sprintf("SELECT id, name, description, price FROM %s WHERE %s LIKE '%%%s%%' ORDER BY name LIMIT 50", table, column, term)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &description, &price); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","description":"%s","price":%.2f}`, id, name, description, price)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
